def main() -> None:
    doc = Document(INPUT)
    for index, text in REPLACEMENTS.items():
        paragraph = doc.paragraphs[index]
        if paragraph.runs:
            first_run = paragraph.runs[0]
            first_run.text = text
            for run in paragraph.runs[1:]:
                run.text = ""
        else:
            paragraph.add_run(text)
    banned = "таким образом"
    hits = [
        (i, paragraph.text)
        for i, paragraph in enumerate(doc.paragraphs)
        if banned in paragraph.text.lower()
    ]
    if hits:
        raise RuntimeError(f"Found banned phrase in paragraphs: {[i for i, _ in hits]}")
    doc.save(OUTPUT)
    print(OUTPUT.resolve())


if __name__ == "__main__":
    main()
